        cmd(7, 0)

        # Turn 90 degrees (by moving East or West based on x)
        if x < 4:
            if x % 2 == 0:
                cmd(1, 90)  # East
            else:
                cmd(1, 270)  # West
            cmd(7, 1)
            for step in range(5):
                time.sleep(0.5)
            cmd(7, 0)

print("Grid search complete")
