import subprocess, time

def read_sensors():
    r = subprocess.run(f'timeout 0.2 cat /dev/robot/d2', shell=True, capture_output=True, text=True)
    try:
        return [float(x) for x in r.stdout.strip().split(',')]
    except:
        return []

def cmd(p, v):
    subprocess.run(f'echo "{v}" > /dev/robot/d{p}', shell=True, capture_output=True, timeout=0.5)

print("Checking sensors by direction...")

for heading in [0, 45, 90, 135, 180, 225, 270, 315]:
    cmd(1, heading)
    time.sleep(0.5)

    sensors = read_sensors()
    if sensors:
        max_idx = sensors.index(max(sensors))
        max_val = max(sensors)
        print(f"Heading {heading:3d}: max at sensor {max_idx:2d} = {max_val:.3f}")

