            if data:
                print(f"d{port}: {data[:100]}")
            else:
                print(f"d{port}: (empty)")
        except:
            print(f"d{port}: (read error)")
        os.close(fd)
    except Exception as e:
        print(f"d{port}: Error - {e}")

